<script setup>
import { onMounted, reactive, ref } from "vue";
import Layout from "../../layouts/main.vue";
import LoadingState from "../../components/ui/loading-state.vue";
import { riskMatrixApi } from "../../services/risk-matrix-api";
import { formatRiskDate, formatRiskError, showRiskError, showRiskSuccess } from "../../components/risk-prevention/module-utils";

const loading=ref(true);const actions=ref([]);const meta=ref({});const filters=reactive({status:"",due:"",search:"",page:1});const editing=ref(null);let timer;
async function load(){loading.value=true;try{const data=await riskMatrixApi.programs(filters);actions.value=data.data||[];meta.value={current_page:data.current_page,last_page:data.last_page,total:data.total};}catch(error){showRiskError(formatRiskError(error));}finally{loading.value=false;}}
function filter(){clearTimeout(timer);timer=setTimeout(()=>{filters.page=1;load();},300);}
function edit(action){editing.value={...action,progress_percentage:Number(action.progress_percentage||0),actual_completion_date:action.actual_completion_date||null};}
async function save(){try{const response=await riskMatrixApi.updateAction(editing.value.id,{status:editing.value.status,progress_percentage:editing.value.progress_percentage,actual_completion_date:editing.value.actual_completion_date,verification_result:editing.value.verification_result});showRiskSuccess(response.message);editing.value=null;await load();}catch(error){showRiskError(formatRiskError(error));}}
async function verify(action){const notes=window.prompt("Resultado y observaciones de verificación:");if(!notes)return;const result=window.confirm("¿La medida fue efectiva? Aceptar = efectiva; Cancelar = ineficaz")?"effective":"ineffective";try{const response=await riskMatrixApi.verifyAction(action.id,{result,notes});showRiskSuccess(response.message);await load();}catch(error){showRiskError(formatRiskError(error,"La verificación requiere evidencia."));}}
onMounted(load);
</script>

<template><Layout><div class="program-hero"><div><span>Prevención de Riesgos · Ejecución</span><h3>Programa de Trabajo Preventivo</h3><p>Medidas provenientes de matrices aprobadas, responsables, vencimientos y verificación basada en evidencia.</p></div><router-link to="/risk-prevention/matrices" class="btn btn-light"><i class="bx bx-grid-alt"></i> Ver matrices</router-link></div><section class="program-panel"><header><div class="search"><i class="bx bx-search"></i><input v-model="filters.search" placeholder="Buscar medida…" @input="filter"/></div><select v-model="filters.due" class="form-select" @change="filter"><option value="">Todos los vencimientos</option><option value="overdue">Vencidas</option><option value="upcoming">Próximas 15 días</option><option value="completed">Implementadas / verificadas</option></select><select v-model="filters.status" class="form-select" @change="filter"><option value="">Todos los estados</option><option v-for="item in ['pending','planned','in_progress','implemented','verified','ineffective','overdue','cancelled']" :key="item" :value="item">{{item}}</option></select><strong>{{meta.total||0}} acciones</strong></header><LoadingState v-if="loading" message="Priorizando acciones preventivas…"/><div v-else class="action-list"><article v-for="action in actions" :key="action.id" :class="{overdue:action.due_date&&new Date(action.due_date)<new Date()&&!['verified','cancelled'].includes(action.status)}"><div class="action-icon"><i class="bx bx-shield-quarter"></i></div><div class="action-main"><span>{{action.program?.version?.matrix?.code}} · {{action.hierarchy_type}}</span><h6>{{action.action_description}}</h6><p>{{action.control?.risk?.specific_risk_name}} · {{action.control?.risk?.task?.activity_name}}</p></div><div class="owner"><span>Responsable</span><strong>{{action.responsible?.name||'Sin asignar'}}</strong></div><div class="due"><span>Vencimiento</span><strong>{{formatRiskDate(action.due_date)}}</strong></div><div class="progress"><div><span :style="{width:`${action.progress_percentage}%`}"></span></div><strong>{{action.progress_percentage}}%</strong></div><span class="status" :class="`status--${action.status}`">{{action.status}}</span><div class="actions"><button title="Actualizar seguimiento" @click="edit(action)"><i class="bx bx-edit"></i></button><button v-if="action.status==='implemented'" title="Verificar con evidencia" @click="verify(action)"><i class="bx bx-check-shield"></i></button></div></article><div v-if="!actions.length" class="empty"><i class="bx bx-task-x"></i><strong>No hay acciones para los filtros aplicados</strong></div></div><footer><span>Página {{meta.current_page||1}} de {{meta.last_page||1}}</span><div><button class="btn btn-sm btn-light" :disabled="meta.current_page<=1" @click="filters.page--;load()">Anterior</button><button class="btn btn-sm btn-light" :disabled="meta.current_page>=meta.last_page" @click="filters.page++;load()">Siguiente</button></div></footer></section>
<div v-if="editing" class="modal-backdrop-custom" @click.self="editing=null"><section class="edit-modal"><header><div><span>Seguimiento operativo</span><h5>Actualizar medida</h5></div><button @click="editing=null"><i class="bx bx-x"></i></button></header><p>{{editing.action_description}}</p><label><span>Estado</span><select v-model="editing.status" class="form-select"><option v-for="item in ['pending','planned','in_progress','implemented','ineffective','cancelled']" :key="item" :value="item">{{item}}</option></select></label><label><span>Avance: {{editing.progress_percentage}}%</span><input v-model.number="editing.progress_percentage" type="range" min="0" max="100" class="form-range"/></label><label><span>Fecha real de término</span><input v-model="editing.actual_completion_date" type="date" class="form-control"/></label><footer><button class="btn btn-light" @click="editing=null">Cancelar</button><button class="btn btn-primary" @click="save">Guardar seguimiento</button></footer></section></div></Layout></template>

<style scoped>
.program-hero{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;padding:1.15rem 1.3rem;border-radius:13px;background:linear-gradient(125deg,#16334c,#146c68);color:#fff}.program-hero span{font-size:.58rem;font-weight:800;text-transform:uppercase}.program-hero h3{margin:.15rem 0}.program-hero p{margin:0;color:#d0e8e5;font-size:.68rem}.program-hero .btn{display:inline-flex;align-items:center;gap:.3rem}.program-panel{overflow:hidden;margin-top:.8rem;border:1px solid #e0e7ee;border-radius:11px;background:#fff}.program-panel>header{display:grid;grid-template-columns:1fr 190px 190px auto;align-items:center;gap:.5rem;padding:.7rem .8rem;border-bottom:1px solid #e9edf2}.search{display:flex;align-items:center;gap:.35rem;padding:.4rem .55rem;border:1px solid #d5dee7;border-radius:7px}.search input{width:100%;border:0;outline:0;font-size:.69rem}.program-panel .form-select{font-size:.66rem}.program-panel>header>strong{color:#667085;font-size:.62rem}.action-list{display:grid}.action-list article{display:grid;grid-template-columns:40px minmax(230px,1fr) 150px 100px 110px auto 70px;align-items:center;gap:.55rem;padding:.65rem .8rem;border-bottom:1px solid #edf0f3}.action-list article.overdue{border-left:4px solid #b42318;background:#fffafa}.action-icon{display:grid;place-items:center;width:36px;height:36px;border-radius:9px;background:#eaf5f3;color:#16806f;font-size:1.1rem}.action-main span,.action-main h6,.action-main p,.owner span,.owner strong,.due span,.due strong{display:block}.action-main span,.action-main p,.owner span,.due span{color:#667085;font-size:.55rem}.action-main h6{margin:.1rem 0;font-size:.67rem}.action-main p{margin:0}.owner strong,.due strong{font-size:.62rem}.progress{display:flex;align-items:center;gap:.4rem}.progress>div{width:70px;height:6px;overflow:hidden;border-radius:99px;background:#e6eaf0}.progress>div span{display:block;height:100%;background:#16806f}.progress strong{font-size:.58rem}.status{padding:.2rem .35rem;border-radius:99px;background:#f2f4f7;color:#536174;font-size:.52rem;font-weight:700;white-space:nowrap}.status--overdue,.status--ineffective{background:#fff1f2;color:#be123c}.status--verified{background:#f0fdf4;color:#15803d}.status--in_progress,.status--implemented{background:#eff6ff;color:#1d4ed8}.actions{display:flex;gap:.2rem}.actions button{display:grid;place-items:center;width:29px;height:29px;border:1px solid #d6dee7;border-radius:6px;background:#fff;color:#28536f}.empty{display:grid;place-items:center;min-height:280px;color:#667085}.empty i{font-size:2rem}.program-panel>footer{display:flex;justify-content:space-between;padding:.65rem .8rem;color:#667085;font-size:.61rem}.program-panel>footer>div{display:flex;gap:.3rem}.modal-backdrop-custom{position:fixed;z-index:1100;inset:0;display:grid;place-items:center;padding:1rem;background:rgba(16,24,40,.52)}.edit-modal{width:min(520px,100%);padding:1rem;border-radius:12px;background:#fff}.edit-modal>header{display:flex;justify-content:space-between}.edit-modal header span,.edit-modal label span{display:block;color:#667085;font-size:.58rem}.edit-modal h5{margin:.1rem 0}.edit-modal header button{border:0;background:none;font-size:1.3rem}.edit-modal p{padding:.6rem;border-radius:7px;background:#f7f9fb;font-size:.65rem}.edit-modal label{display:block;margin-top:.6rem}.edit-modal>footer{display:flex;justify-content:flex-end;gap:.4rem;margin-top:.8rem}@media(max-width:1100px){.action-list article{grid-template-columns:40px 1fr 130px 100px}.progress,.status,.actions{grid-column:auto}.program-panel>header{grid-template-columns:1fr 1fr}.program-panel>header .search{grid-column:1/-1}}@media(max-width:650px){.program-hero{align-items:flex-start;flex-direction:column}.action-list article{grid-template-columns:40px 1fr}.owner,.due,.progress,.status,.actions{grid-column:2}.program-panel>header{grid-template-columns:1fr}}
</style>
